import{_ as n,o as i,c as h,a2 as a}from"./chunks/framework.O93z6AWZ.js";const s=JSON.parse('{"title":"Đề tài 2.1 — Mày đay (Dr May Day)","description":"","frontmatter":{"title":"Đề tài 2.1 — Mày đay (Dr May Day)"},"headers":[],"relativePath":"du_an/may_day.md","filePath":"du_an/may_day.md"}'),o={name:"du_an/may_day.md"};function c(r,t,e,g,d,l){return i(),h("div",null,[...t[0]||(t[0]=[a('<h1 id="đe-tai-2-1-phan-vung-va-đo-luong-san-phu-qua-anh-da-ho-tro-quan-ly-benh-may-đay" tabindex="-1">Đề tài 2.1: Phân vùng và đo lường sẩn phù qua ảnh da hỗ trợ quản lý bệnh Mày đay <a class="header-anchor" href="#đe-tai-2-1-phan-vung-va-đo-luong-san-phu-qua-anh-da-ho-tro-quan-ly-benh-may-đay" aria-label="Permalink to &quot;Đề tài 2.1: Phân vùng và đo lường sẩn phù qua ảnh da hỗ trợ quản lý bệnh Mày đay&quot;">​</a></h1><p><strong>Nhóm đề tài:</strong> 2. Ảnh Y tế (Fundus/Dermatology) · <strong>Trạng thái:</strong> ⚠️ Y văn quy mô nhỏ (6 bản ghi thử nghiệm) — cần mở rộng trước khi dùng chính thức</p><div class="tip custom-block"><p class="custom-block-title">📥 Bộ tài liệu đầy đủ trên GitHub</p><p>Dữ liệu thô và mã nguồn chi tiết được lưu trữ <strong>Private</strong> trên kho GitHub của bộ môn (để đảm bảo sinh viên tự thực hiện). Sinh viên tham khảo thông tin mức độ cơ bản tại đây.</p></div><p>Đọc trước <strong><a href="/hmyt-book/du_an_mon_hoc">Khung Quản Lý &amp; Rubric</a></strong>.</p><hr><h2 id="_1-phat-bieu-bai-toan" tabindex="-1">1. Phát biểu bài toán <a class="header-anchor" href="#_1-phat-bieu-bai-toan" aria-label="Permalink to &quot;1. Phát biểu bài toán&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Câu hỏi nghiên cứu</strong></td><td>Phân vùng (segmentation) và đo lường diện tích/mức độ sẩn phù qua ảnh chụp da để hỗ trợ đánh giá độ nặng bệnh Mày đay (Urticaria)</td></tr><tr><td><strong>Input (X)</strong></td><td>Ảnh chụp da vùng tổn thương, lý tưởng có vật đối chuẩn kích thước (thước kẻ/color card)</td></tr><tr><td><strong>Output (Y)</strong></td><td>Bản đồ phân vùng sẩn phù (mask) + diện tích quy đổi ra cm², hoặc điểm số độ nặng (Urticaria Activity Score)</td></tr><tr><td><strong>Dataset gợi ý</strong></td><td>Tự thu thập có vật đối chuẩn, hoặc bộ Dermoscopy mã nguồn mở</td></tr><tr><td><strong>Thách thức đặc thù</strong></td><td>Da nhiều lông, nhiễu ánh sáng; quy đổi pixel → kích thước thực (cm) để tính điểm diện tích chuẩn xác</td></tr></tbody></table><hr><h2 id="_2-y-van-khoi-đong-1-include-3-context-2-exclude" tabindex="-1">2. Y văn khởi động (1 INCLUDE + 3 CONTEXT + 2 EXCLUDE) <a class="header-anchor" href="#_2-y-van-khoi-đong-1-include-3-context-2-exclude" aria-label="Permalink to &quot;2. Y văn khởi động (1 INCLUDE + 3 CONTEXT + 2 EXCLUDE)&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Chủ đề khan hiếm tài liệu trực tiếp</p><p>Chỉ tìm được <strong>1 tiền lệ trực tiếp</strong> cho bài toán thị giác máy tính trên mày đay — và bản thân nó là đếm/phát hiện hive (hive counting) chứ chưa phải phân vùng pixel-level (Dice/IoU) như câu hỏi nghiên cứu đặt ra. Đây là dấu hiệu <strong>khoảng trống nghiên cứu thực sự</strong> — phù hợp làm luận điểm mở đầu (Introduction) cho báo cáo của nhóm, nhưng cũng có nghĩa nhóm sẽ khó tìm đủ ≥10 bài trực tiếp và cần mở rộng phạm vi tìm kiếm sang các bệnh da liễu khác có phương pháp tương tự (đo diện tích tổn thương da nói chung).</p></div><h3 id="ban-ghi-include" tabindex="-1">Bản ghi INCLUDE <a class="header-anchor" href="#ban-ghi-include" aria-label="Permalink to &quot;Bản ghi INCLUDE&quot;">​</a></h3><p><strong><code>maccarthy2024auas</code></strong> — <em>Automatic Urticaria Activity Score: Deep Learning-Based Automatic Hive Counting for Urticaria Severity Assessment</em>, JID Innovations 2024 (doi: <a href="https://doi.org/10.1016/j.xjidi.2023.100218" target="_blank" rel="noreferrer">10.1016/j.xjidi.2023.100218</a>). Mô hình Legit.Health-UAS-HiveNet, 313 ảnh gán nhãn bởi 5 chuyên gia, Krippendorff alpha = 0,826 (đếm hive) / 0,603 (phân độ nặng).</p><div class="warning custom-block"><p class="custom-block-title">Bài học về đối chiếu tiêu chí literal vs tinh thần</p><p>Đây là bài toán <strong>đếm/phát hiện</strong> hive, báo cáo <strong>Krippendorff alpha</strong> (đồng thuận đánh giá) — không phải Dice/IoU theo đúng nghĩa đen của tiêu chí đưa vào ban đầu. Vẫn giữ lại vì thỏa mãn trục outcome rộng hơn (&quot;Severity correlation&quot;) và là bằng chứng gần nhất hiện có. <strong>Bài học cho sinh viên:</strong> khi một bài gần khớp nhưng không khớp 100% câu chữ tiêu chí, đừng tự ý loại hay nhận — ghi rõ mâu thuẫn và đưa ra hội đồng/giảng viên quyết định.</p></div><h3 id="ban-ghi-context-3" tabindex="-1">Bản ghi CONTEXT (3) <a class="header-anchor" href="#ban-ghi-context-3" aria-label="Permalink to &quot;Bản ghi CONTEXT (3)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Citekey</th><th>Lý do CONTEXT</th></tr></thead><tbody><tr><td><code>gomes2024deeplearning</code></td><td>Sai population (Skin Prick Test, không phải mày đay mạn tính) nhưng là tiền lệ kỹ thuật gần nhất về đo kích thước sẩn phù (N=5.844 ảnh, segmentation accuracy 85,88%)</td></tr><tr><td><code>choy2023systematic</code></td><td>Systematic review — nền tảng dẫn nhập, không đưa vào Evidence Matrix định lượng</td></tr><tr><td><code>pathania2023aiurticaria</code></td><td>Bài bình luận/quan điểm ngắn, không có dữ liệu segmentation riêng</td></tr></tbody></table><h3 id="ban-ghi-exclude-2" tabindex="-1">Bản ghi EXCLUDE (2) <a class="header-anchor" href="#ban-ghi-exclude-2" aria-label="Permalink to &quot;Bản ghi EXCLUDE (2)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Citekey</th><th>Lý do EXCLUDE</th></tr></thead><tbody><tr><td><code>yang2025llmurticaria</code></td><td>Sai intervention — đánh giá chatbot LLM trả lời văn bản, không có thị giác máy tính</td></tr><tr><td><code>unverified2024yolov8skin</code></td><td>Sai trọng tâm + <strong>DOI chưa tra được</strong> qua Crossref — không dùng làm bằng chứng</td></tr></tbody></table><hr><h2 id="_3-workflow-timeline" tabindex="-1">3. Workflow &amp; Timeline <a class="header-anchor" href="#_3-workflow-timeline" aria-label="Permalink to &quot;3. Workflow &amp; Timeline&quot;">​</a></h2><p>Áp dụng workflow 7 giai đoạn / timeline 15 tuần chung (xem mẫu chi tiết ở <a href="/hmyt-book/du_an/roi_loan_nhip_tim">Đề tài 1.2 — Rối loạn nhịp tim</a>). Lưu ý đặc thù:</p><ul><li><strong>gd1-proposal:</strong> vì khan hiếm tài liệu trực tiếp, nhóm cần dành nhiều thời gian hơn ở giai đoạn này để mở rộng tìm kiếm (dermoscopy nói chung, đo diện tích tổn thương da bằng CV) thay vì chỉ tìm đúng từ khóa &quot;urticaria&quot;.</li><li><strong>gd2-dataset-eda:</strong> nếu tự thu thập ảnh, bắt buộc có vật đối chuẩn kích thước trong khung hình ngay từ đầu (không thể bổ sung sau).</li><li><strong>gd3-preprocessing:</strong> chuẩn hóa ánh sáng/màu sắc, xử lý nhiễu lông/tóc, augmentation phù hợp với biến thiên góc chụp thực tế.</li><li><strong>gd6-evaluation-xai:</strong> dùng Grad-CAM/U-Net segmentation map làm minh chứng XAI trực quan; đối chiếu điểm số tự động với đánh giá của chuyên gia (giống cách <code>maccarthy2024auas</code> dùng Krippendorff alpha).</li></ul><hr><h2 id="_4-viec-con-ton-đong-tu-bao-cao-y-van" tabindex="-1">4. Việc còn tồn đọng (từ báo cáo y văn) <a class="header-anchor" href="#_4-viec-con-ton-đong-tu-bao-cao-y-van" aria-label="Permalink to &quot;4. Việc còn tồn đọng (từ báo cáo y văn)&quot;">​</a></h2><ol><li>Lần rà soát này mới có 6 bản ghi tìm thủ công — sinh viên cần đầu tư đáng kể vào việc tìm kiếm mở rộng để đạt ≥10 bài, đây là chủ đề khó nhất về khối lượng tài liệu sẵn có trong toàn ngân hàng đề tài.</li></ol><div class="warning custom-block"><p class="custom-block-title">Zero-Hallucination</p><p>Mọi trích dẫn phải khớp key có thật trong <code>.bib</code> đã xác minh DOI qua Crossref API (trừ <code>unverified2024yolov8skin</code> — bị loại đúng vì lý do này).</p></div>',25)])])}const m=n(o,[["render",c]]);export{s as __pageData,m as default};
